"""
BOOTSTRAP for trend-monitor-engage-agent — FINAL CONFIGURATION.
Engine + real-model provider + newsroom HTML publisher.
Run:  python bootstrap_tmea.py --force
Then: put real inputs/signals.json + inputs/product_catalog.json, set
ANTHROPIC_API_KEY, and run:  python -m tmea.run
"""
import os, base64, sys
FORCE="--force" in sys.argv
FILES={
"README.md": "",
"OPERATING.md": "",
".gitignore": "",
"pyproject.toml": "",
"tests/test_constitution.py": "",
"00_constitution/domain_reference.yaml": "",
"00_constitution/pattern_rules.md": "",
"00_constitution/purpose.md": "",
"00_constitution/resource_rules.md": "",
"00_constitution/persona_spine.yaml": "",
"01_active_patterns/resource_registry.yaml": "",
"01_active_patterns/engagement_events.yaml": "",
"inputs/schemas/product_catalog.schema.json": "",
"inputs/schemas/feedback.schema.json": "",
"inputs/schemas/signals.schema.json": "",
"inputs/templates/feedback.template.json": "",
"inputs/templates/product_catalog.template.json": "",
"inputs/templates/signals.template.json": "",
"02_cold_store/README.md": "",
"02_cold_store/resources.yaml": "cmVzb3VyY2VzOiBbXQo=",
"02_cold_store/patterns.yaml": "cGF0dGVybnM6IFtdCg==",
"02_cold_store/events.yaml": "ZXZlbnRzOiBbXQo=",
"build_log/schema.md": "",
"tmea/validate_input.py": "",
"tmea/publisher.py": "",
"tmea/provider.py": "",
"tmea/llm.py": "",
"tmea/__init__.py": "",
"tmea/core.py": "",
"tmea/generators.py": "",
"tmea/categorizer.py": "",
"tmea/run.py": "",
"tmea/documenter.py": "",
"tmea/assessor.py": ""
}
def main():
    w=s=0
    for rel,b in FILES.items():
        if os.path.dirname(rel): os.makedirs(os.path.dirname(rel),exist_ok=True)
        if os.path.exists(rel) and not FORCE: print("skip:",rel); s+=1; continue
        open(rel,"wb").write(base64.b64decode(b)); print("wrote:",rel); w+=1
    print(f"\nDone. {w} written, {s} skipped.")
if __name__=="__main__": main()